        Config({'XBLOCK': 256, 'YBLOCK': 1}, num_warps=8, num_stages=4),
        Config({'XBLOCK': 512, 'YBLOCK': 1}, num_warps=8, num_stages=4),
        Config({'XBLOCK': 128, 'YBLOCK': 1}, num_warps=4, num_stages=4),
        Config({'XBLOCK': 64,  'YBLOCK': 4}, num_warps=4, num_stages=3),
        Config({'XBLOCK': 128, 'YBLOCK': 4}, num_warps=4, num_stages=3),
        Config({'XBLOCK': 256, 'YBLOCK': 4}, num_warps=8, num_stages=3),
        Config({'XBLOCK': 128, 'YBLOCK': 8}, num_warps=4, num_stages=3),
        Config({'XBLOCK': 256, 'YBLOCK': 8}, num_warps=8, num_stages=4),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: constexpr, XBLOCK: constexpr):
    tmp0 = tl.load(in_ptr + strided_index, mask=ymask & xmask, eviction_policy='evict_first')
    tl.store(out_ptr + transposed_index, tmp0, mask=ymask & xmask)

def launcher():
    grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
    kernel[grid](in_ptr, out_ptr, ynumel, xnumel)  # no fixed tile args
